"""Package the completed first-stage audit without rerunning models or statistics."""
import json,shutil
from pathlib import Path
import pandas as pd
from study import OUT,REPO,sha,save

def main():
 first=json.loads((OUT/'verification.json').read_text());independent=json.loads((OUT/'independent_full_replay_verification.json').read_text());assert all(first.values())
 failed=[k for k,v in independent.items() if not v];assert failed==['set_II_all_completed_test_logits_exact_replay']
 numerical=json.loads((OUT/'setII_replay_tf32_on.json').read_text())['results']['test'];assert numerical['severe_group_decision_changes']==0 and all(v in [None,0] for v in numerical['per_label_decision_changes'])
 proto=json.loads((OUT/'protocol.json').read_text());assert all(sha(p)==h for p,h in proto['source_hashes'].items())
 replay=json.loads((OUT/'full_replay_receipt.json').read_text());assert all(replay['models'][n]['max_logit_error']==0 for n in ['raw_full12','raw_II','set_full12'])
 cache=json.loads((OUT/'cache_receipt.json').read_text());representation=json.loads((OUT/'representation_receipt.json').read_text());names=['raw_full12','raw_II','set_full12','set_II'];receipts={n:json.loads((OUT/n/'receipt.json').read_text()) for n in names}
 resource={'input_cache_seconds':cache['seconds'],'phase_detection_fit_and_features_seconds':representation['seconds'],'model_run_total_seconds_including_load_validation_and_prediction':sum(r['seconds'] for r in receipts.values()),'training_plus_validation_epoch_seconds':sum(pd.read_csv(OUT/n/'history.csv').seconds.sum() for n in names),'GPU_peak_allocated_GiB_by_model':{n:r['peak_GPU_GiB'] for n,r in receipts.items()},'verification_seconds':replay['seconds_all_verification'],'GPU':'NVIDIA A100-PCIE-40GB','cost_USD':None,'notes':'Existing hardware, no cloud cost estimate. GPU allocation excludes context; sampled utilization in gpu_samples.csv covers only part of the primary queue. CPU/NFS preprocessing and loading are separate from training.'};save(OUT/'resource_summary.json',resource)
 point=pd.read_csv(OUT/'summary.csv').set_index('model');stats=json.loads((OUT/'paired_statistics.json').read_text());clinical=pd.read_csv(OUT/'clinical_metrics.csv');severe=clinical[clinical.endpoint.eq('source_severe_tachyarrhythmia')].set_index('model')
 decision={'scope':'first-stage15label source-record classification under fixed protocols, not patient-disjoint clinical validation','SetOperator_superiority_supported':False,'LeadII_macroAUPRC_difference_common':float(point.loc['set_II','macro_AUPRC_common_completed']-point.loc['raw_II','macro_AUPRC_common_completed']),'LeadII_severe_sensitivity_difference_all':float(severe.loc['set_II','sensitivity_all_eligible']-severe.loc['raw_II','sensitivity_all_eligible']),'intervals':stats['comparisons']['leadII_set_minus_raw'],'reason':'Raw model has higher matched ranking and severe-group all-record sensitivity; original PhaseKME has substantial diagnosis-dependent representation failures.','temporal_extension_justified_by_this_evidence':False,'FLEX_or_rare_loss_matrix_launched':False,'next_gate':'Review this negative first-stage result; resolve representation coverage and development-fit questions before architecture expansion. Obtain patient linkage and existing event timing before clinical validation claims.','patient_linkage':'unresolved; author request local draft not sent','abstract_drafted':False,'bitwise_reproduction_all_models':False,'numerical_replay_qualification':'SetII fresh-process probabilities differ by at most0.000342; no test classification changes; macroAUPRC change0.0000054. Three other models replay exactly. Numerical cause not fully isolated.'};save(OUT/'decision.json',decision)
 addition=['','## First-stage decision','', 'The reduced-lead SetOperator advantage is not supported under this protocol. The matched raw LeadII model exceeds even the current SetOperator representation-availability sensitivity ceiling for the severe source group. Better classification optimization alone cannot recover records that do not obtain an input representation. An ordered-beat extension using the same extraction contract does not address that failure. No FLEX, temporal or imbalance grid was launched.', '', 'The full12 SetOperator development curve was still improving at the40epoch cap. This limits architecture-capacity conclusions, while the deterministic representation-coverage limit remains. The conclusion is about this implemented protocol, not every possible SetOperator optimization.', '', 'Visual review showed that source diagnosis labels do not establish event presence throughout the first10seconds. For example critical:Z01089 has a large-amplitude oscillatory early segment followed by much smaller activity; critical:Z02864 has repeated organized deflections in its shown prefix despite a whole-record torsades label. These observations do not clinically adjudicate artifact or event identity and do not justify relabeling. The reported clinical-group sensitivities are agreement with source-record labels, not validated active-event detection.', '', 'No independently interpretable clinical advantage has been established, so no HRS abstract was drafted. Existing deidentified patient groups and event onsets/offsets have been requested in a local author draft; no message was sent and no linkage has been received.', '', 'Per-label bootstrap intervals are descriptive and unadjusted. Draws without a positive for any fixed macro label remain undefined; the primary macro interval has1957valid draws out of2000, rather than replacing undefined values with zero.', '', f"Resource totals: input cache {resource['input_cache_seconds']/60:.2f}minutes; beat extraction/kernel fitting/features {resource['phase_detection_fit_and_features_seconds']/60:.2f}minutes; four model runs {resource['model_run_total_seconds_including_load_validation_and_prediction']/60:.2f}minutes including loading and evaluation. Summed timed training/validation epochs {resource['training_plus_validation_epoch_seconds']/60:.2f}minutes. Independent verification is reported separately.", '', f"Verification: all{len(first)} primary checks pass; {sum(bool(v) for v in independent.values())}/{len(independent)} independent exact checks pass. Three models replay all test logits exactly. SetII fails bitwise fresh-process replay: maximum probability drift0.000342, no test classification changes, macroAUPRC drift0.0000054; the qualification remains open and is not relabeled as a pass. Four contract tests and four real-model GPU gradient witnesses also passed.", '', 'Source provenance: Figshare v3 https://doi.org/10.6084/m9.figshare.31229326.v3; data descriptor https://doi.org/10.1038/s41597-026-08108-z.']
 with (OUT/'REPORT.md').open('a') as file:file.write('\n'.join(addition)+'\n')
 snapshot=OUT/'source_snapshot';snapshot.mkdir(exist_ok=True)
 sources=[Path(p) for p in proto['source_hashes']]+[p for p in (REPO/'experiments/zzu_multilabel').iterdir() if p.is_file()]
 for p in sources:
  target=snapshot/p.relative_to(REPO);target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,target)
 save(OUT/'source_snapshot_hashes.json',{str(p.relative_to(snapshot)):sha(p) for p in snapshot.rglob('*') if p.is_file()})
 # The source cache digest was computed after creation and every later access is read-only.
 # Feature digests are freshly computed after their final write, in response_hashes.sha256.
 known={'waveforms_mV.npy':cache['cache_sha256']}
 for line in (OUT/'response_hashes.sha256').read_text().splitlines():
  digest,path=line.split(maxsplit=1);known[Path(path).name]=digest
 assert set(known)=={'waveforms_mV.npy','responses_full12.npy','responses_II.npy'}
 save(OUT/'manifest_hash_sources.json',{'waveforms_mV.npy':'complete SHA256 computed by preparation after flush; frozen and read-only throughout all later stages','responses_full12.npy':'fresh sha256sum after final feature write','responses_II.npy':'fresh sha256sum after final feature write','other_files':'freshly hashed during packaging'})
 manifest={}
 for p in OUT.rglob('*'):
  if not p.is_file() or p.name=='delivery_manifest.json':continue
  key=str(p.relative_to(OUT));manifest[key]=known[key] if key in known else sha(p)
 save(OUT/'delivery_manifest.json',manifest);print('PACKAGED',len(manifest),'files',flush=True)
if __name__=='__main__':main()
